const nowYear = new Date().getFullYear();
const data = {
  patterns: [
    { id: 'wolt', name: 'Wolt', type: 'częsty', count: 8, sum: 428.4, amount: null, threshold: '4 × / miesiąc', excess: 84.0, status: '' },
    { id: 'netflix', name: 'Netflix', type: 'stały', count: 1, sum: 55, amount: 55, threshold: '55,00 zł', excess: 0, status: 'zmiana kwoty' },
    { id: 'sklep', name: 'Sklep osiedlowy', type: 'częsty', count: 11, sum: 348.6, amount: null, threshold: '8 × / miesiąc', excess: 61.2, status: '' },
    { id: 'paliwo', name: 'Stacja paliw', type: 'częsty', count: 4, sum: 298.2, amount: null, threshold: '—', excess: 0, status: 'nowy' },
    { id: 'cloud', name: 'CloudBox', type: 'stały', count: 1, sum: 39.99, amount: 39.99, threshold: '39,99 zł', excess: 0, status: '' }, { id: 'excluded-coffee', name: 'Coffee Corner', type: 'częsty', count: 6, sum: 96, amount: null, threshold: '—', excess: 0, status: 'wykluczony', excluded: true }
  ],
  months: [
    { label: 'paź 25', value: 72 }, { label: 'lis 25', value: 98 }, { label: 'gru 25', value: 142 },
    { label: 'sty 26', value: 116 }, { label: 'lut 26', value: 181 }, { label: 'mar 26', value: 148 },
    { label: 'kwi 26', value: 242 }, { label: 'maj 26', value: 284, current: true }
  ],
  transactions: [
    ['25.05.2026', 'WOLT*WARSAW', 72.40, true], ['22.05.2026', 'WOLT*WARSAW', 48.00, true],
    ['18.05.2026', 'WOLT*WARSAW', 39.90, false], ['11.05.2026', 'WOLT*WARSAW', 56.30, false],
    ['06.05.2026', 'WOLT*WARSAW', 44.00, false], ['02.05.2026', 'WOLT*WARSAW', 33.20, false]
  ]
};
const money = value => `${Number(value).toLocaleString('pl-PL', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} zł`;
const mark = (className = 'brand-mark', light = false) => `<svg class="${className}" viewBox="0 0 32 32" aria-hidden="true"><path fill="${light ? '#F2F1EC' : 'currentColor'}" fill-rule="evenodd" d="M5 29V3h13l9 9-8 8 9 9h-8l-9-9v9zm6-21v8h5l4-4-4-4z"/></svg>`;
const icon = (name, size = 18) => `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true"><use href="assets/icons/ui/ui.svg#${name}"/></svg>`;
const brand = (light = false) => `<a class="brand" href="#/">${mark('brand-mark', light)}<span>Rytm</span></a>`;
const footer = () => `<footer class="footer container"><span>© ${nowYear} Rytm. Spokojnie o pieniądzach.</span><span><a href="#">Prywatność</a><a href="#">Kontakt</a></span></footer>`;
const header = () => `<header class="site-header container">${brand()}<nav class="nav"><a href="#/how-it-works">Jak działa</a><a href="#/for-who">Dla kogo</a><a class="btn btn-ghost" href="#/login">Zaloguj się</a><a class="btn btn-primary" href="#/register">Zacznij</a></nav></header>`;
const badge = (label, kind = '') => `<span class="badge ${kind}">${label}</span>`;
const toast = (message, kind = 'success') => `<div class="toast ${kind}" role="status">${icon(kind === 'error' ? 'warning' : kind === 'info' ? 'info' : 'success', 16)}<span>${message}</span><button aria-label="Zamknij" onclick="this.parentElement.remove()">${icon('close', 15)}</button></div>`;
const sideLink = (href, label, ico, active = false) => `<a class="${active ? 'active' : ''}" href="${href}">${icon(ico, 17)}<span>${label}</span></a>`;
const mobileNav = active => `<nav class="mobile-nav" aria-label="Nawigacja aplikacji">${sideLink('#/home', 'Przegląd', 'overview', active === 'home')}${sideLink('#/patterns', 'Wzorce', 'patterns', active === 'patterns')}${sideLink('#/fixed', 'Stałe', 'fixed', active === 'fixed')}${sideLink('#/imports', 'Importy', 'import', active === 'imports')}${sideLink('#/settings', 'Konto', 'settings', active === 'settings')}</nav>`;
const appHeader = () => `<header class="dash-header">${brand()}<div class="dash-user"><span class="muted">maj 2026</span><button class="btn btn-ghost" onclick="location.hash='#/'">Wyjdź</button></div></header>`;
const sidebar = active => `<aside class="side"><div class="side-label">Widok</div>${sideLink('#/home', 'Przegląd', 'overview', active === 'home')}${sideLink('#/patterns', 'Wzorce wydatków', 'patterns', active === 'patterns')}${sideLink('#/fixed', 'Koszty stałe', 'fixed', active === 'fixed')}<div class="side-label">Dane</div>${sideLink('#/imports', 'Importy CSV', 'import', active === 'imports')}<div class="side-bottom">${sideLink('#/settings', 'Ustawienia', 'settings', active === 'settings')}</div></aside>`;
const appShell = (active, content) => `<div class="dash-shell">${appHeader()}<div class="dash-body">${sidebar(active)}<main class="dash-main">${content}</main></div>${mobileNav(active)}</div>`;

function landing() { return `<div class="screen"><div class="container">${header()}</div><main><section class="hero container"><div><div class="eyebrow">Spokojnie o pieniądzach</div><h1>Pieniądze uciekają w <em>rytmie.</em><br/>Rytm ten rytm pokazuje.</h1><p>Wgraj wyciąg bankowy i zobacz, które wydatki wracają zbyt często. Bez oceniania. Z jasną granicą, którą ustawiasz sam.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Zobacz swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Jak to działa?</a></div><div class="hero-note">Darmowy start · dane zostają u Ciebie</div></div><div class="hero-card"><div class="mini-top"><span>Twój miesiąc</span><span>maj 2026</span></div><div class="mini-total">3 842,60 zł</div><div class="mini-sub">wydatki rozpoznane</div><div class="bars"><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar"></i><i class="bar accent"></i><i class="bar accent"></i></div><div class="rhythm-row"><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r"></i><i class="rhythm-r accent"></i><i class="rhythm-r accent"></i></div></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Bez arkusza</div><h2>Trzy kroki do jasności.</h2></div><span class="muted">Wystarczy jeden wieczór w miesiącu.</span></div><div class="three-cols"><article class="feature"><h3>01 — Wgraj CSV</h3><p>Wrzuć wyciąg z banku. Rytm rozpozna sprzedawców i powtarzające się kwoty.</p></article><article class="feature"><h3>02 — Ustaw granicę</h3><p>Sam decydujesz, ile kaw, dostaw lub subskrypcji mieści się w Twoim miesiącu.</p></article><article class="feature"><h3>03 — Zobacz ponad progiem</h3><p>Nadwyżka trafia do widoku „ponad progiem w tym miesiącu”. Bez wstydu, z konkretem.</p></article></div></section><section class="cta-band"><div class="container"><h2>Zobacz, gdzie cicho<br/>ucieka pieniądz.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`; }
function howItWorks() { return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero container"><div><div class="eyebrow">Jak działa Rytm</div><h1>Najpierw wzorzec.<br/><em>Potem decyzja.</em></h1><p>Rytm porządkuje powtarzalne transakcje, żebyś raz w miesiącu widział to, co zwykle ginie w historii konta.</p><a class="btn btn-primary" href="#/register">Zacznij od swojego CSV <span>↗</span></a></div><div class="sequence-card"><div class="sequence-caption">Jedna granica, wiele powrotów</div><div class="sequence-track"><span class="seq active"></span><span class="seq active"></span><span class="seq active"></span><i></i><span class="seq over"></span><span class="seq over"></span></div><div class="sequence-labels"><span>Twój próg</span><b>Ponad próg</b></div></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Od pliku do obrazu</div><h2>Trzy spokojne kroki.</h2></div><span class="muted">Bez ręcznego kategoryzowania.</span></div><div class="process-grid"><article class="process-card"><span class="process-number">01</span><h3>Wgraj wyciąg</h3><p>Wybierz plik CSV z banku. Rytm czyta datę, sprzedawcę i kwotę, a potem grupuje podobne transakcje.</p><div class="process-line"></div><small>Masz kontrolę nad plikiem</small></article><article class="process-card"><span class="process-number">02</span><h3>Rozpoznaj rytm</h3><p>Stałe koszty i częste zakupy układają się w sekwencje. Widzisz, co wraca co miesiąc, a nie przypadkowy dzień.</p><div class="process-line"></div><small>Wzorzec zamiast szumu</small></article><article class="process-card"><span class="process-number">03</span><h3>Ustaw granicę</h3><p>Próg jest Twój. Rytm zaznacza dopiero kolejne powtórzenia, a ich suma trafia do „ponad progiem w tym miesiącu”.</p><div class="process-line amber"></div><small>Bez oceniania, z konkretem</small></article></div></section><section class="explain-band"><div class="container explain-grid"><div><div class="eyebrow">Co zobaczysz</div><h2>Nie jeden duży wydatek.<br/>Cały jego rytm.</h2></div><div class="explain-list"><div><b>Stałe koszty</b><span>Ta sama usługa, podobna kwota — od razu widać podwyżkę albo nową pozycję.</span></div><div><b>Częste zakupy</b><span>Ten sam sprzedawca niezależnie od kwoty — dostawy, kawa, małe decyzje.</span></div><div><b>Ponad próg</b><span>Rytm nie mówi, co masz robić. Pokazuje miejsce, w którym możesz zdecydować.</span></div></div></div></section><section class="cta-band"><div class="container"><h2>Twój miesiąc ma<br/>swój rytm.</h2><a class="btn btn-amber" href="#/register">Zobacz go</a></div></section></main>${footer()}</div>`; }
function forWho() { return `<div class="screen"><div class="container">${header()}</div><main><section class="sub-hero audience-hero container"><div><div class="eyebrow">Dla kogo jest Rytm</div><h1>Dla osoby, która chce<br/><em>wiedzieć bez liczenia.</em></h1><p>Masz dwa konta, kilka subskrypcji i zero ochoty na kolejny arkusz. Rytm daje Ci jeden spokojny moment prawdy w miesiącu.</p><div class="hero-actions"><a class="btn btn-primary" href="#/register">Sprawdź swój rytm <span>↗</span></a><a class="btn btn-ghost" href="#/how-it-works">Zobacz jak działa</a></div></div><div class="audience-note"><span class="audience-mark">R</span><p>„Nie chcę budżetu<br/>na każdy dzień.<br/><strong>Chcę widzieć wzorce.”</strong></p></div></section><section class="section container"><div class="section-head"><div><div class="eyebrow">Brzmi znajomo?</div><h2>Rytm pasuje do Twojego tempa.</h2></div></div><div class="audience-grid"><article class="audience-card"><span class="card-index">A</span><h3>Pracujesz i ogarniasz dużo</h3><p>Nie potrzebujesz kolejnego systemu do prowadzenia. Potrzebujesz krótkiego, prawdziwego obrazu.</p><a href="#/register">Raz w miesiącu <span>↗</span></a></article><article class="audience-card"><span class="card-index">B</span><h3>Masz wydatki, które wracają</h3><p>Subskrypcje, jedzenie z dowozem, kawa po drodze. Rytm pokaże częstotliwość bez moralizowania.</p><a href="#/register">Zobacz powroty <span>↗</span></a></article><article class="audience-card"><span class="card-index">C</span><h3>Chcesz ustawić własną granicę</h3><p>Nie chodzi o zakaz. Chodzi o moment, w którym nadwyżka staje się widoczna i możesz coś z nią zrobić.</p><a href="#/register">Ustaw swój próg <span>↗</span></a></article></div></section><section class="quote-band"><div class="container"><div class="eyebrow">To nie jest aplikacja do perfekcji</div><h2>To jest aplikacja do<br/><em>większej jasności.</em></h2><p>Rytm zostawia miejsce na normalne życie. Pomaga tylko zauważyć, kiedy małe decyzje zaczynają się powtarzać.</p></div></section><section class="cta-band"><div class="container"><h2>Wystarczy jeden<br/>spokojny wieczór.</h2><a class="btn btn-amber" href="#/register">Utwórz konto</a></div></section></main>${footer()}</div>`; }
function auth(mode) { const reg = mode === 'register'; if (mode === 'reset') return resetPage(); return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:#c79d62">Twój rytm</div><h1>${reg ? 'Zacznij widzieć więcej.' : 'Wróć do swojego rytmu.'}</h1><p>${reg ? 'Jedno konto, jeden spokojny widok Twoich wydatków.' : 'Twoje wzorce wydatków czekają na kolejny miesiąc.'}</p></div></aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault(); ${reg ? "location.hash='#/home'" : "document.getElementById('authError').hidden=false"}"><div class="eyebrow">${reg ? 'Nowe konto' : 'Witaj ponownie'}</div><h1>${reg ? 'Utwórz konto' : 'Zaloguj się'}</h1><p>${reg ? 'Zacznij od adresu e-mail. Resztę ustawisz później.' : 'Wróć do spokojnego widoku swoich wydatków.'}</p><div id="authError" class="inline-alert error" hidden>${icon('warning', 16)}<span>Nie rozpoznaliśmy tego e-maila i hasła. Spróbuj ponownie.</span></div>${reg ? '<div class="field"><label for="name">Imię <span class="optional">opcjonalne</span></label><input id="name" placeholder="np. Ola" /></div>' : ''}<div class="field"><label for="email">E-mail</label><input id="email" type="email" placeholder="ty@przyklad.pl" required /></div><div class="field"><label for="password">Hasło</label><input id="password" type="password" placeholder="••••••••" required /></div>${reg ? '<div class="form-row"><span>Zakładając konto akceptujesz regulamin.</span></div>' : '<div class="form-row"><label><input type="checkbox"/> Zapamiętaj mnie</label><a href="#/reset">Nie pamiętam hasła</a></div>'}<button class="btn btn-primary" type="submit">${reg ? 'Utwórz konto' : 'Zaloguj się'} <span>↗</span></button><div class="auth-footer">${reg ? 'Masz już konto?' : 'Nie masz jeszcze konta?'} <a href="${reg ? '#/login' : '#/register'}">${reg ? 'Zaloguj się' : 'Utwórz je'}</a></div></form></main></div>`; }
function resetPage() { return `<div class="auth-shell"><aside class="auth-visual">${brand(true)}<div class="auth-copy"><div class="eyebrow" style="color:#c79d62">Spokojnie</div><h1>Hasło można ustawić na nowo.</h1><p>Wyślemy Ci prostą instrukcję na adres przypisany do konta.</p></div></aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault();this.innerHTML='<div class=eyebrow>Sprawdź skrzynkę</div><h1>Link jest w drodze.</h1><p>Jeśli konto istnieje, wysłaliśmy instrukcję zmiany hasła.</p><a class=\"btn btn-primary\" href=\"#/login\">Wróć do logowania</a>'"><div class="eyebrow">Nie pamiętam hasła</div><h1>Odzyskaj dostęp.</h1><p>Podaj e-mail, którego używasz w Rytmie.</p><div class="field"><label for="reset-email">E-mail</label><input id="reset-email" type="email" placeholder="ty@przyklad.pl" required /></div><button class="btn btn-primary" type="submit">Wyślij instrukcję <span>↗</span></button><div class="auth-footer"><a href="#/login">Wróć do logowania</a></div></form></main></div>`; }

function trendChart() { const max = Math.max(...data.months.map(m => m.value)); return `<div class="trend monthly-trend">${data.months.map(m => `<i class="tbar ${m.current ? 'hot' : ''}" style="height:${Math.max(12, m.value / max * 100)}%" data-day="${m.label}">${m.current ? '<b>niepełny</b>' : ''}</i>`).join('')}</div><div class="legend"><span><i class="dot"></i> suma ponad progiem</span><span><i class="dot hot"></i> bieżący, niepełny miesiąc</span></div>${data.months.length < 3 ? '<div class="info-panel">Trend pojawi się po 3 miesiącach danych.</div>' : ''}`; }
function dashboard(empty = false) { if (empty) return appShell('home', `<div class="dash-title"><div><div class="eyebrow">Przegląd miesiąca</div><h1>Zacznij od pierwszego importu.</h1><p>Rytm pokaże Ci wzorce, kiedy dostanie pierwszy wyciąg.</p></div></div><section class="empty-dashboard panel"><img src="assets/illustrations/rytm-pusty-stan-jasny.svg" alt="Dokument czekający na import"/><h2>Nie masz jeszcze żadnego importu.</h2><p>Wgraj jeden plik CSV z wyciągu bankowego. Przed importem wybierzesz rachunek i zobaczysz zakres danych.</p><a class="btn btn-primary" href="#/imports/new">Wgraj CSV <span>↗</span></a></section>`); return appShell('home', `<div class="dash-title"><div><div class="eyebrow">Przegląd miesiąca</div><h1>Dzień dobry, Olu.</h1><p>Oto rytm Twoich wydatków w maju.</p></div><a class="btn btn-primary" href="#/imports/new">+ Wgraj CSV</a></div><div class="stats"><article class="stat-card accent"><div class="stat-label">Ponad progiem w tym miesiącu</div><div class="stat-value">284,40 zł</div><div class="stat-foot">+42,20 zł względem kwietnia</div></article><article class="stat-card"><div class="stat-label">Rozpoznane wydatki</div><div class="stat-value">3 842,60 zł</div><div class="stat-foot">64 transakcje · 12 wzorców</div></article><article class="stat-card"><div class="stat-label">Koszty stałe</div><div class="stat-value">1 920 zł</div><div class="stat-foot">2 pozycje podrożały</div></article></div><div class="dash-grid"><section class="panel"><div class="panel-title"><h2>Ponad progiem</h2><span>miesięcznie · wszystkie dane</span></div>${trendChart()}</section><section class="panel"><div class="panel-title"><h2>Co wraca najczęściej</h2><span>próg własny</span></div><div class="list">${data.patterns.slice(0, 3).map(p => `<div class="list-item"><div class="merchant"><span class="merchant-mark">${p.name[0]}</span><div><div class="item-name">${p.name}</div><div class="item-meta">${p.count} razy · próg ${p.threshold}</div></div></div><div class="item-amount ${p.excess ? 'up' : ''}">${p.excess ? '+' : ''}${p.excess ? money(p.excess) : money(p.sum)}</div></div>`).join('')}</div><a class="text-link" href="#/patterns">Zobacz wszystkie wzorce ${icon('arrow', 14)}</a></section></div><section class="import-panel"><div class="import-copy"><span class="import-icon">${icon('import', 18)}</span><div><strong>Dodaj najnowszy wyciąg</strong><span>CSV z Twojego banku · plik nie jest przechowywany po imporcie</span></div></div><a class="btn btn-ghost" href="#/imports/new">Wybierz plik</a></section>`); }
function patternRows(list) { return list.map(p => `<tr data-name="${p.name.toLowerCase()}" data-sum="${p.sum}" data-count="${p.count}"><td><a class="table-name" href="#/patterns/${p.id}"><span class="merchant-mark">${p.name[0]}</span><span>${p.name}</span></a></td><td>${badge(p.type, p.type === 'stały' ? 'fixed' : 'frequent')}</td><td>${p.count}</td><td>${money(p.sum)}</td><td>${p.threshold}</td><td>${p.excess ? `<span class="excess-value">${money(p.excess)}</span>` : '—'} ${p.status ? badge(p.status, p.status === 'nowy' ? 'new' : 'changed') : ''}</td><td><a class="icon-button" href="#/patterns/${p.id}" aria-label="Otwórz wzorzec">${icon('arrow', 16)}</a></td></tr>`).join(''); }
function patterns(empty = false) { if (empty) return emptyView('patterns'); return appShell('patterns', '<div class="dash-title"><div><div class="eyebrow">Wzorce wydatków</div><h1>To, co wraca.</h1><p>Każdy sprzedawca ma jeden typ. Możesz zmienić go w dowolnym momencie.</p></div><a class="btn btn-primary" href="#/imports/new">+ Wgraj CSV</a></div><div class="toolbar"><label class="search-field">'+icon('search',16)+'<input id="patternSearch" placeholder="Szukaj sprzedawcy" /></label><label class="select-field">'+icon('sort',16)+'<select id="patternSort"><option value="sum">Sortuj: suma</option><option value="count">Sortuj: liczba</option><option value="name">Sortuj: nazwa</option></select></label></div><section class="panel table-panel"><div class="table-wrap"><table id="patternsTable"><thead><tr><th>Sprzedawca</th><th>Typ</th><th>Wystąpienia</th><th>Suma</th><th>Próg</th><th>Ponad progiem</th><th></th></tr></thead><tbody>'+patternRows(data.patterns.filter(function(p){return !p.excluded;}))+'</tbody></table></div><div class="table-foot"><span>5 wzorców · wszystkie miesiące</span><button class="btn btn-ghost" onclick="showToast(\'To już wszystkie wzorce.\',\'info\')">Pokaż więcej</button></div></section><section class="excluded-section"><button class="excluded-toggle" onclick="this.parentElement.classList.toggle(\'open\')">'+icon('arrow',14)+' Wykluczone <span>1 wzorzec</span></button><div class="excluded-list panel"><div class="list-item"><div class="merchant"><span class="merchant-mark">C</span><div><div class="item-name">Coffee Corner</div><div class="item-meta">Wykluczony z analizy</div></div></div><button class="text-button" onclick="restorePattern()">Przywróć</button></div></div></section>'); }

function thresholdEditor(p) { const noThreshold = p.threshold === '—'; return `<div class="threshold-editor"><div class="threshold-switch"><button class="threshold-option active">${p.type === 'stały' ? 'Akceptowana kwota' : 'Liczba na miesiąc'}</button>${p.type === 'częsty' ? '<button class="threshold-option">Suma na miesiąc</button>' : ''}</div><div class="threshold-fields"><label><span>${p.type === 'stały' ? 'Kwota' : 'Liczba wystąpień'}</span><div class="input-suffix"><input type="number" value="${noThreshold ? '' : p.type === 'stały' ? '55' : '4'}" placeholder="—"/><b>${p.type === 'stały' ? 'zł' : '×'}</b></div></label></div><p class="threshold-note">${noThreshold ? 'Ustaw próg, aby Rytm mógł oznaczać kolejne wystąpienia jako ponad próg.' : 'Po przekroczeniu granicy kolejne wystąpienia zostaną oznaczone etykietą „ponad próg”.'}</p><div class="threshold-actions"><button class="btn btn-primary" onclick="showToast('Próg zapisany.','success')">${noThreshold ? 'Ustaw próg' : 'Zapisz próg'}</button>${!noThreshold ? '<button class="text-button" onclick="showToast(\'Próg usunięty.\',\'info\')">Usuń próg</button>' : ''}</div></div>`; }
function patternDetail(id) { const p = data.patterns.find(item => item.id === id) || data.patterns[0]; return appShell('patterns', `<div class="detail-top"><a class="back-link" href="#/patterns">${icon('arrow-left', 15)} Wróć do wzorców</a><div class="detail-actions"><button class="btn btn-ghost" onclick="openModal('patternActions')">${icon('more', 16)} Akcje</button></div></div><section class="detail-heading"><div><div class="eyebrow">${badge(p.type, p.type === 'stały' ? 'fixed' : 'frequent')} wzorzec</div><h1>${p.name}</h1><p>${p.type === 'stały' ? 'Sprzedawca o stałej, powtarzalnej kwocie.' : 'Sprzedawca, który wraca niezależnie od kwoty.'}</p></div><div class="detail-total"><span>Suma w maju</span><strong>${money(p.sum)}</strong><small>${p.count} wystąpień</small></div></section><section class="detail-grid"><div class="panel"><div class="panel-title"><h2>Próg wzorca</h2><span>${p.threshold === '—' ? 'brak ustawionego progu' : 'aktywny'}</span></div>${thresholdEditor(p)}</div><div class="panel"><div class="panel-title"><h2>Wystąpienia w miesiącu</h2><label class="select-field small"><select><option>maj 2026</option><option>kwi 2026</option><option>mar 2026</option></select></label></div><div class="sequence-large">${Array.from({ length: p.count }, (_, i) => `<span class="seq ${i >= (p.type === 'stały' ? 1 : 4) && p.excess ? 'over' : ''}"></span>`).join('')}</div><div class="sequence-labels"><span>W ramach progu</span><b>Ponad próg</b></div></div></section><section class="panel transactions-panel"><div class="panel-title"><h2>Transakcje z wyciągu</h2><span>opis surowy · kwota</span></div><div class="list">${data.transactions.map(t => `<div class="list-item"><div><div class="item-name">${t[0]}</div><div class="item-meta">${t[1]}</div></div><div class="transaction-right"><strong>${money(t[2])}</strong>${t[3] ? badge('ponad próg', 'excess') : ''}</div></div>`).join('')}</div></section>`); }

function fixedCosts() { return appShell('fixed', `<div class="dash-title"><div><div class="eyebrow">Koszty stałe</div><h1>Co zmieniło się samo?</h1><p>Rytm porównuje miesiące kalendarzowe i pokazuje różnice.</p></div></div><section class="fixed-section"><div class="section-label"><h2>Zmieniły kwotę</h2><span>2 pozycje</span></div><div class="fixed-list panel"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">N</span><div><strong>Netflix</strong><small>20.05.2026 · poprzednio 49,00 zł</small></div></div><div class="fixed-change"><span>55,00 zł</span><b>+6,00 zł</b></div></div><div class="fixed-row"><div class="merchant"><span class="merchant-mark">C</span><div><strong>CloudBox</strong><small>02.05.2026 · poprzednio 34,99 zł</small></div></div><div class="fixed-change"><span>39,99 zł</span><b>+5,00 zł</b></div></div></div></section><section class="fixed-section"><div class="section-label"><h2>Nowe w tym miesiącu</h2><span>1 pozycja</span></div><div class="fixed-list panel"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">M</span><div><strong>MusicFlow</strong><small>pierwsze wystąpienie · 15.05.2026</small></div></div><div class="fixed-change"><span>19,99 zł</span>${badge('nowy', 'new')}</div></div></div></section><section class="fixed-section"><div class="section-label"><h2>Bez zmian</h2><span>3 pozycje</span></div><div class="fixed-list panel compact"><div class="fixed-row"><div class="merchant"><span class="merchant-mark">A</span><strong>Adobe</strong></div><span>79,00 zł</span></div><div class="fixed-row"><div class="merchant"><span class="merchant-mark">H</span><strong>Hosting</strong></div><span>29,00 zł</span></div></div></section>`); }
function emptyView(kind) { var c={patterns:['Wzorce pojawią się po pierwszym imporcie.','Tutaj zobaczysz sprzedawców, którzy wracają w Twoich wydatkach.'],fixed:['Koszty stałe pojawią się po pierwszym imporcie.','Tutaj zobaczysz subskrypcje i opłaty, które zmieniły kwotę lub pojawiły się po raz pierwszy.'],imports:['Nie masz jeszcze żadnego importu.','Tutaj znajdziesz historię wgranych wyciągów i ich zakresy dat.']}[kind]; var label=kind==='patterns'?'Wzorce wydatków':kind==='fixed'?'Koszty stałe':'Importy CSV'; return appShell(kind,'<div class="dash-title"><div><div class="eyebrow">'+label+'</div><h1>'+c[0]+'</h1><p>'+c[1]+'</p></div></div><section class="view-empty panel"><div class="empty-mark">'+icon(kind==='imports'?'import':kind==='fixed'?'fixed':'patterns',28)+'</div><h2>Wgraj pierwszy wyciąg</h2><p>Jeden plik CSV wystarczy, aby Rytm mógł rozpoznać Twój rytm wydatków.</p><a class="btn btn-primary" href="#/imports/new">Wgraj CSV <span>↗</span></a></section>'); }
function resetNew(state) { if(state==='expired') return '<div class="auth-shell"><aside class="auth-visual">'+brand(true)+'</aside><main class="auth-form-wrap"><div class="auth-form"><div class="inline-alert error">'+icon('warning',16)+'<span>Link wygasł. Wyślij nowy link, aby kontynuować.</span></div><a class="btn btn-primary" href="#/reset">Wyślij nowy link <span>↗</span></a></div></main></div>'; if(state==='success') return '<div class="auth-shell"><aside class="auth-visual">'+brand(true)+'</aside><main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Gotowe</div><h1>Hasło zostało zmienione.</h1><p>Możesz teraz zalogować się do swojego rytmu.</p><a class="btn btn-primary" href="#/login">Zaloguj się <span>↗</span></a></div></main></div>'; return '<div class="auth-shell"><aside class="auth-visual">'+brand(true)+'</aside><main class="auth-form-wrap"><form class="auth-form" onsubmit="event.preventDefault();location.hash=\'#/reset/new?success=1\'"><div class="eyebrow">Nowe hasło</div><h1>Ustaw nowe hasło.</h1><p>Hasło musi mieć co najmniej 6 znaków.</p><div class="field"><label>Nowe hasło</label><input type="password" minlength="6" required /></div><div class="field"><label>Powtórz hasło</label><input type="password" minlength="6" required /></div><button class="btn btn-primary" type="submit">Zapisz nowe hasło <span>↗</span></button></form></main></div>'; }
function confirmEmail() { return '<div class="auth-shell"><aside class="auth-visual">'+brand(true)+'</aside><main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Sprawdź skrzynkę</div><h1>Link jest w drodze.</h1><p>Wysłaliśmy link aktywacyjny na podany adres e-mail. Kliknij go, aby dokończyć rejestrację.</p><div class="inline-alert info">'+icon('info',16)+'<span>Nie widzisz wiadomości? Sprawdź folder spam.</span></div><button id="resendButton" class="btn btn-ghost" onclick="startResend()">Wyślij ponownie</button><div class="auth-footer"><a href="#/login">Wróć do logowania</a></div></div></main></div>'; }
function startResend() { var b=document.getElementById('resendButton'); if(!b)return; var n=60;b.disabled=true;b.textContent='Wyślij ponownie ('+n+'s)';var t=setInterval(function(){n--;b.textContent=n?'Wyślij ponownie ('+n+'s)':'Wyślij ponownie';if(!n){clearInterval(t);b.disabled=false;}},1000); }
function restorePattern() { var r=document.querySelector('.excluded-list .list-item'); if(r) r.innerHTML='<div class="merchant"><span class="merchant-mark">C</span><div><div class="item-name">Coffee Corner</div><div class="item-meta">Przywrócony do analizy</div></div></div>'+badge('przywrócony','new'); showToast('Wzorzec przywrócony do analizy.','success'); }

function imports() { return appShell('imports', `<div class="dash-title"><div><div class="eyebrow">Importy CSV</div><h1>Twoje źródła danych.</h1><p>Każdy import możesz cofnąć. Plik CSV nie jest przechowywany po imporcie.</p></div><a class="btn btn-primary" href="#/imports/new">+ Nowy import</a></div><section class="panel import-table"><div class="table-wrap"><table><thead><tr><th>Data importu</th><th>Rachunek</th><th>Zakres dat</th><th>Obciążenia</th><th></th></tr></thead><tbody><tr><td>28.05.2026</td><td>ING · Konto główne</td><td>01.05–28.05.2026</td><td>64</td><td><button class="text-button danger" onclick="openModal('deleteImport')">Usuń import</button></td></tr><tr><td>30.04.2026</td><td>ING · Konto główne</td><td>01.04–30.04.2026</td><td>71</td><td><button class="text-button danger" onclick="openModal('deleteImport')">Usuń import</button></td></tr></tbody></table></div></section>`); }
function importsNew() { return appShell('imports', '<div class="dash-title"><div><div class="eyebrow">Nowy import</div><h1>Dodaj wyciąg.</h1><p>Wybierzesz jeden rachunek z pliku. Import obejmuje tylko obciążenia.</p></div><a class="back-link" href="#/imports">'+icon('arrow-left',15)+' Wróć do importów</a></div><div class="import-flow"><div class="flow-step active"><b>1</b><span>Plik CSV</span></div><div class="flow-line"></div><div class="flow-step"><b>2</b><span>Rachunek</span></div><div class="flow-line"></div><div class="flow-step"><b>3</b><span>Podsumowanie</span></div></div><section class="panel upload-zone"><div class="upload-symbol">'+icon('upload',28)+'</div><h2>Upuść plik CSV tutaj</h2><p>Obsługujemy wyciągi ING Bank Śląski w PLN. Santander wkrótce.</p><button class="btn btn-primary" onclick="document.getElementById(\'csvInput\').click()">Wybierz plik</button><input id="csvInput" type="file" hidden accept=".csv" onchange="document.getElementById(\'uploadState\').innerHTML=uploadReady()"/><div id="uploadState"></div></section><section class="import-errors"><div class="inline-alert error">'+icon('warning',16)+'<span><strong>Nieznany format pliku.</strong> Obsługujemy: ING Bank Śląski. Santander wkrótce. <button class="text-button" onclick="document.getElementById(\'csvInput\').click()">Wybierz inny plik</button></span></div><div class="inline-alert error">'+icon('warning',16)+'<span><strong>Waluta inna niż PLN.</strong> Wybierz plik rachunku prowadzonego w PLN. <button class="text-button" onclick="document.getElementById(\'csvInput\').click()">Wybierz inny plik</button></span></div><div class="inline-alert error">'+icon('warning',16)+'<span><strong>Brak obciążeń.</strong> Ten plik zawiera tylko wpływy lub jest pusty. <button class="text-button" onclick="document.getElementById(\'csvInput\').click()">Wybierz inny plik</button></span></div></section>'); }

function uploadReady() { return `<div class="upload-ready">${icon('success', 16)} <span>wyciag-maj-2026.csv · rozpoznano format ING</span><button class="text-button" onclick="location.hash='#/imports/new/account'">Dalej ${icon('arrow', 14)}</button></div>`; }
function importAccount() { return appShell('imports', `<div class="dash-title"><div><div class="eyebrow">Nowy import · krok 2 z 3</div><h1>Wybierz rachunek.</h1><p>Ten plik zawiera trzy rachunki. Domyślnie zaznaczyliśmy ten z największą liczbą transakcji.</p></div></div><section class="panel account-picker"><label class="account-option selected"><input type="radio" name="account" checked/><span><strong>Konto główne · •• 4821</strong><small>ING Bank Śląski · 64 transakcje</small></span><b>wybrane</b></label><label class="account-option"><input type="radio" name="account"/><span><strong>Konto VAT · •• 1094</strong><small>ING Bank Śląski · 12 transakcji</small></span></label><label class="account-option"><input type="radio" name="account"/><span><strong>Oszczędnościowe · •• 8842</strong><small>ING Bank Śląski · 4 transakcje</small></span></label><div class="flow-actions"><a class="btn btn-ghost" href="#/imports/new">Wstecz</a><a class="btn btn-primary" href="#/imports/new/summary">Dalej <span>↗</span></a></div></section>`); }
function importSummary() { return appShell('imports', '<div class="dash-title"><div><div class="eyebrow">Nowy import · krok 3 z 3</div><h1>Sprawdź przed importem.</h1><p>Import obejmuje jeden rachunek i tylko obciążenia.</p></div></div><section class="panel summary-panel"><div class="summary-grid"><div><span>Rachunek</span><strong>ING · Konto główne · •• 4821</strong></div><div><span>Zakres dat</span><strong>01.05–28.05.2026</strong></div><div><span>Obciążenia do importu</span><strong>64 transakcje</strong></div><div><span>Pominięte wpływy / zwroty</span><strong>12 transakcji</strong></div></div><div class="inline-alert error">'+icon('warning',16)+'<span>Ten zakres nachodzi na istniejący import: <a href="#/imports">1 marca – 31 maja 2026</a>. Wybierz inny plik albo wróć do importów.</span></div><div class="flow-actions"><a class="btn btn-ghost" href="#/imports/new">Wybierz inny plik</a><a class="btn btn-ghost" href="#/imports">Wróć do importów</a></div></section>'); }

function importResult() { return appShell('imports', `<section class="result-state"><div class="result-icon">${icon('success', 30)}</div><div class="eyebrow">Import gotowy</div><h1>Wzorce są już widoczne.</h1><p>Dodaliśmy 64 obciążenia i znaleźliśmy 12 wzorców dla konta głównego.</p><div class="result-stats"><div><strong>64</strong><span>transakcje</span></div><div><strong>12</strong><span>wzorców</span></div><div><strong>3</strong><span>koszty stałe</span></div></div><div class="hero-actions"><a class="btn btn-primary" href="#/patterns">Zobacz wzorce <span>↗</span></a><a class="btn btn-ghost" href="#/home">Przejdź do przeglądu</a></div></section>`); }
function settings() { return appShell('settings', `<div class="dash-title"><div><div class="eyebrow">Ustawienia / konto</div><h1>Twoje konto.</h1><p>Sprawdź dane i ustawienia prywatności.</p></div></div><section class="panel settings-panel"><div class="panel-title"><h2>Dane logowania</h2></div><div class="settings-row"><span>E-mail</span><strong>ola@example.com</strong><button class="btn btn-ghost">Zmień</button></div><div class="settings-row"><span>Hasło</span><strong>••••••••</strong><a class="btn btn-ghost" href="#/reset">Zmień hasło</a></div><div class="settings-row"><span>Przetwarzanie danych</span><p>Plik CSV nie jest przechowywany po imporcie. Konto przechowuje wynik analizy i Twoje decyzje.</p></div></section><section class="panel danger-panel"><div><div class="eyebrow">Strefa destrukcyjna</div><h2>Usuń konto</h2><p>Usunięcie konta kasuje importy, wzorce, progi i wszystkie decyzje bez śladu.</p></div><button class="btn btn-danger" onclick="openModal('deleteAccount')">Usuń konto</button></section>`); }
function components() { return `<div class="screen"><div class="container">${header()}</div><main class="component-page container"><div class="eyebrow">Biblioteka UI</div><h1>Komponenty Rytmu.</h1><p class="muted">Przykłady stanów i zasad, które składają się na interfejs aplikacji.</p><section class="component-section"><h2>Badge i etykiety</h2><div class="component-row">${badge('stały', 'fixed')}${badge('częsty', 'frequent')}${badge('ponad próg', 'excess')}${badge('wykluczony', 'excluded')}${badge('nowy', 'new')}${badge('zmiana kwoty', 'changed')}</div></section><section class="component-section"><h2>Alerty</h2><div class="component-alerts"><div class="inline-alert success">${icon('success', 16)} Sukces — próg zapisany.</div><div class="inline-alert error">${icon('warning', 16)} Błąd — sprawdź plik CSV.</div><div class="inline-alert info">${icon('info', 16)} Informacja — trend pojawi się po 3 miesiącach.</div></div></section><section class="component-section"><h2>Formularze, skeleton, tabela</h2><div class="component-row"><label class="search-field">${icon('search', 16)}<input placeholder="Szukaj" /></label><label class="select-field"><select><option>Wybierz opcję</option><option>Stały</option><option>Częsty</option></select></label><button class="btn btn-primary">Zapisz</button><button class="btn btn-ghost" onclick="openModal('patternActions')">Otwórz dialog</button></div><div class="skeleton-demo"><i></i><i></i><i></i></div></section></main>${footer()}</div>`; }
function modal(type) { const isDelete = type === 'deleteAccount'; const isImport = type === 'deleteImport'; return `<div class="modal-backdrop" id="modal" role="dialog" aria-modal="true"><div class="modal"><button class="modal-close" onclick="closeModal()" aria-label="Zamknij">${icon('close', 17)}</button>${isDelete ? `<div class="eyebrow">Usunięcie konta</div><h2>Usunąć konto bez śladu?</h2><p>Ta decyzja usunie wszystkie importy, wzorce i progi. Wpisz <strong>USUŃ</strong>, aby potwierdzić.</p><input id="confirmDelete" class="modal-input" placeholder="USUŃ"/><button class="btn btn-danger" onclick="document.getElementById('modal').remove();showToast('Konto nie zostało usunięte w prototypie.','info')">Usuń konto</button>` : isImport ? `<div class="eyebrow">Cofnij import</div><h2>Usunąć import z maja?</h2><p>Wzorce wykryte w tym imporcie zostaną przeliczone. Tę decyzję można cofnąć przez ponowny import.</p><button class="btn btn-danger" onclick="closeModal();showToast('Import usunięty w prototypie.','success')">Usuń import</button>` : `<div class="eyebrow">Akcje na wzorcu</div><h2>Zarządzaj wzorcem.</h2><p>Decyzje dotyczą wszystkich kolejnych miesięcy. Możesz je później odwrócić w ustawieniach wzorca.</p><div class="modal-actions"><button class="btn btn-ghost" onclick="closeModal();showToast('Tryb scalania jest gotowy do podpięcia.','info')">${icon('merge', 16)} Scal z…</button><button class="btn btn-ghost" onclick="closeModal();showToast('Typ wzorca zmieniony.','success')">${icon('switch', 16)} Zmień typ</button><button class="btn btn-ghost" onclick="closeModal();showToast('Możesz zmienić nazwę inline.','info')">${icon('edit', 16)} Zmień nazwę</button><button class="btn btn-ghost" onclick="closeModal();showToast('Wzorzec wykluczony z analizy.','success')">${icon('exclude', 16)} Wyklucz z analizy</button></div>`}</div></div>`; }
function openModal(type) { document.body.insertAdjacentHTML('beforeend', modal(type)); }
function closeModal() { document.getElementById('modal')?.remove(); }
function showToast(message, kind) { document.body.insertAdjacentHTML('beforeend', toast(message, kind)); setTimeout(() => document.querySelector('.toast')?.remove(), 3400); }
function bindInteractions() { const search = document.getElementById('patternSearch'); const sort = document.getElementById('patternSort'); const update = () => { const term = (search?.value || '').toLowerCase(); let list = data.patterns.filter(p => p.name.toLowerCase().includes(term)); const key = sort?.value || 'sum'; list.sort((a, b) => key === 'name' ? a.name.localeCompare(b.name) : b[key] - a[key]); const tbody = document.querySelector('#patternsTable tbody'); if (tbody) tbody.innerHTML = patternRows(list); }; search?.addEventListener('input', update); sort?.addEventListener('change', update); }
function togglePassword(id,button) { var input=document.getElementById(id); if(!input)return; input.type=input.type==='password'?'text':'password'; button.textContent=input.type==='password'?'Pokaż':'Ukryj'; }
function applyDashboardState(path) { if(path==='#/home-no-name') { var h=document.querySelector('.dash-title h1'); var lead=document.querySelector('.dash-title p'); if(h) h.textContent='Dzień dobry.'; if(lead) lead.textContent='Twój maj w jednym spokojnym widoku.'; } }
function applyPatternState(path) { if(path.indexOf('#/patterns/excluded-coffee')===0) { var main=document.querySelector('.dash-main'); if(main) main.insertAdjacentHTML('afterbegin','<div class="inline-alert info excluded-banner">'+icon('info',16)+'<span>Wykluczony z analizy</span><button class="text-button" onclick="restorePattern()">Przywróć</button></div>'); } }
function applyAuthState(path,q) { if(path==='#/login'&&q.get('confirmed')) { var f=document.querySelector('.auth-form'); if(f) f.insertAdjacentHTML('afterbegin','<div class="inline-alert success">'+icon('success',16)+'<span>E-mail potwierdzony — zaloguj się.</span></div>'); } if(path==='#/register'&&q.get('error')) { var f=document.querySelector('.auth-form'); if(f) f.insertAdjacentHTML('afterbegin','<div class="inline-alert error">'+icon('warning',16)+'<span>'+ (q.get('error')==='occupied' ? 'Ten e-mail jest już zajęty. <a href="#/login">Zaloguj się</a> lub <a href="#/reset">Nie pamiętam hasła</a>.' : 'Nie udało się utworzyć konta. Sprawdź adres e-mail i spróbuj ponownie.') +'</span></div>'); } document.querySelectorAll('.auth-form input[type=password]').forEach(function(input){ if(input.parentElement.classList.contains('password-control'))return; var wrap=document.createElement('div');wrap.className='password-control';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);var b=document.createElement('button');b.type='button';b.className='password-toggle';b.textContent='Pokaż';b.onclick=function(){togglePassword(input.id,b);};wrap.appendChild(b); }); }
function render() { var raw=location.hash||'#/'; var parts=raw.slice(1).split('?'); var p='#'+parts[0]; var q=new URLSearchParams(parts[1]||''); var html=p==='#/reset/new'?resetNew(q.get('success')?'success':q.get('state')||''):p==='#/confirm-email'?confirmEmail():p==='#/patterns-empty'?emptyView('patterns'):p==='#/fixed-empty'?emptyView('fixed'):p==='#/imports-empty'?emptyView('imports'):p==='#/home-no-name'?dashboard(false,false):p==='#/login'&&q.get('confirmed')?auth('login') : p==='#/register'&&q.get('error')?auth('register'):null; if(!html){ html=p==='#/login'?auth('login'):p==='#/register'?auth('register'):p==='#/reset'?resetPage():p==='#/home'?dashboard():p==='#/home-empty'?dashboard(true):p==='#/patterns'?patterns():p.startsWith('#/patterns/')?patternDetail(p.split('/')[2]):p==='#/fixed'?fixedCosts():p==='#/imports'?imports():p==='#/imports/new'?importsNew():p==='#/imports/new/account'?importAccount():p==='#/imports/new/summary'?importSummary():p==='#/imports/result'?importResult():p==='#/settings'?settings():p==='#/components'?components():p==='#/how-it-works'?howItWorks():p==='#/for-who'?forWho():landing(); } document.getElementById('app').innerHTML=html; bindInteractions(); applyAuthState(p,q); applyDashboardState(p); applyPatternState(p); window.scrollTo(0,0); }
window.addEventListener('hashchange', render); render();
